<?php

declare(strict_types=1);

require __DIR__ . '/app/V2/Database.php';
require __DIR__ . '/app/V2/Intelligence/Schema.php';
require __DIR__ . '/app/V2/Intelligence/CurrencyFormatter.php';
require __DIR__ . '/app/V2/Intelligence/MarketExplorerService.php';

use LittyWatch\V2\Database;
use LittyWatch\V2\Intelligence\CurrencyFormatter;
use LittyWatch\V2\Intelligence\MarketExplorerService;

$pdo = Database::connect(__DIR__);
$service = new MarketExplorerService($pdo);
$money = new CurrencyFormatter(__DIR__);
$filters = [
    'q' => $_GET['q'] ?? '',
    'sort' => $_GET['sort'] ?? 'activity',
    'side' => $_GET['side'] ?? '',
    'confidence' => $_GET['confidence'] ?? 0,
    'liquidity' => $_GET['liquidity'] ?? 0,
];
$rows = $service->search($filters, 200);
$counts = $service->counts();
function h(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function selected(string $a, string $b): string { return $a === $b ? ' selected' : ''; }
function scoreClass(int $score): string { return $score >= 75 ? 'good' : ($score >= 45 ? 'mid' : 'low'); }
?>
