<section class="stats"><article class="card"><small>Markten</small><strong><?= $counts['markets'] ?></strong></article><article class="card"><small>Tweezijdige markt</small><strong><?= $counts['two_sided'] ?></strong></article><article class="card"><small>Deal score ≥ 60</small><strong><?= $counts['deals'] ?></strong></article><article class="card"><small>Hoge zekerheid</small><strong><?= $counts['high_confidence'] ?></strong></article></section>
<form class="panel filters" method="get"><input name="q" value="<?= h($filters['q']) ?>" placeholder="Zoek item of market key"><select name="sort"><option value="activity"<?= selected((string)$filters['sort'],'activity') ?>>Nieuwste</option><option value="deal"<?= selected((string)$filters['sort'],'deal') ?>>Beste deals</option><option value="liquidity"<?= selected((string)$filters['sort'],'liquidity') ?>>Liquiditeit</option><option value="confidence"<?= selected((string)$filters['sort'],'confidence') ?>>Zekerheid</option><option value="demand"<?= selected((string)$filters['sort'],'demand') ?>>Meeste vraag</option><option value="supply"<?= selected((string)$filters['sort'],'supply') ?>>Meeste aanbod</option><option value="item"<?= selected((string)$filters['sort'],'item') ?>>Itemnaam</option></select><select name="side"><option value=""<?= selected((string)$filters['side'],'') ?>>Alle markten</option><option value="both"<?= selected((string)$filters['side'],'both') ?>>WTB én WTS</option><option value="buy"<?= selected((string)$filters['side'],'buy') ?>>Met WTB</option><option value="sell"<?= selected((string)$filters['side'],'sell') ?>>Met WTS</option></select><select name="confidence"><option value="0">Alle zekerheid</option><option value="50"<?= selected((string)$filters['confidence'],'50') ?>>≥ 50%</option><option value="70"<?= selected((string)$filters['confidence'],'70') ?>>≥ 70%</option><option value="85"<?= selected((string)$filters['confidence'],'85') ?>>≥ 85%</option></select><select name="liquidity"><option value="0">Alle liquiditeit</option><option value="45"<?= selected((string)$filters['liquidity'],'45') ?>>Gemiddeld+</option><option value="75"<?= selected((string)$filters['liquidity'],'75') ?>>Hoog</option></select><button>Filteren</button></form>
<section class="panel"><div class="table"><div class="row header"><span>Markt</span><span>Mediaan WTB</span><span>Mediaan WTS</span><span>Spread</span><span>Deal</span><span>Zekerheid</span><span>Liquiditeit</span><span>Volgen</span></div><?php if(!$rows): ?><div class="empty">Geen markten gevonden met deze filters.</div><?php endif; ?><?php foreach($rows as $r): $spread=$r['spread_ecto']!==null?(float)$r['spread_ecto']:null; ?><a class="row" href="/v2-market.php?key=<?= rawurlencode((string)$r['market_key']) ?>"><div class="item"><strong><?= h($r['item']) ?></strong><code><?= h($r['market_key']) ?></code></div><div class="price"><strong><?= h($money->ecto($r['median_wtb_ecto']!==null?(float)$r['median_wtb_ecto']:null)) ?></strong><small><?= h($money->armbrace($r['median_wtb_ecto']!==null?(float)$r['median_wtb_ecto']:null)) ?></small></div><div class="price"><strong><?= h($money->ecto($r['median_wts_ecto']!==null?(float)$r['median_wts_ecto']:null)) ?></strong><small><?= h($money->armbrace($r['median_wts_ecto']!==null?(float)$r['median_wts_ecto']:null)) ?></small></div><div class="<?= $spread!==null&&$spread>=0?'good':'low' ?> badge"><?= $spread===null?'—':h($money->ecto($spread)) ?></div><div><strong><?= (int)$r['deal_score'] ?></strong>/100</div><div><span class="badge <?= scoreClass((int)$r['confidence_score']) ?>"><?= (int)$r['confidence_score'] ?>%</span></div><div><span class="badge <?= scoreClass((int)$r['liquidity_score']) ?>"><?= h($r['liquidity_label']) ?></span></div><div class="star"><?= (int)$r['watched']===1?'★':'☆' ?></div></a><?php endforeach; ?></div></section></main></body></html>
